// ---------- saved preferences ----------
// Persisted in the browser. Wrapped because some embedded previews block storage.
function readPref(key, allowed, fallback) {
  try {
    const v = window.localStorage.getItem(key);
    return allowed.indexOf(v) > -1 ? v : fallback;
  } catch (e) {
    return fallback;
  }
}
function writePref(key, value) {
  try {
    window.localStorage.setItem(key, value);
  } catch (e) {
    /* storage unavailable; preference lasts for this session only */
  }
}

// ---------- helpers ----------
function rng(seed) {
  let t = seed >>> 0;
  return function () {
    t += 0x6d2b79f5;
    let x = Math.imul(t ^ (t >>> 15), 1 | t);
    x ^= x + Math.imul(x ^ (x >>> 7), 61 | x);
    return ((x ^ (x >>> 14)) >>> 0) / 4294967296;
  };
}

function shuffle(arr, rand) {
  const a = arr.slice();
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

const ALL = [];
BANK.forEach((c) => c.qs.forEach((q, i) => ALL.push({ ...q, ch: c.ch, id: c.ch * 1000 + i })));

function split(pool, size, seed) {
  const s = shuffle(pool, rng(seed));
  return [0, 1, 2].map((i) => s.slice(i * size, i * size + size));
}

const GROUPS = [
  { key: "g2", sets: split(ALL.filter((q) => q.ch <= 8), 85, 771103) },
  { key: "g3", sets: split(ALL.filter((q) => q.ch >= 9), 85, 445209) },
  { key: "g1", sets: split(ALL, 100, 20260913) },
];
const MOCK_COUNT = GROUPS.reduce((n, g) => n + g.sets.length, 0);

function prepare(list, seed) {
  const rand = rng(seed);
  return shuffle(list, rand).map((q) => {
    const pairs = q.o.map((text, idx) => ({
      text,
      hi: q.hi && q.hi.o ? q.hi.o[idx] : null,
      correct: idx === q.a,
    }));
    const mixed = shuffle(pairs, rand);
    return {
      ...q,
      opts: mixed.map((p) => p.text),
      optsHi: mixed.map((p) => p.hi),
      ans: mixed.findIndex((p) => p.correct),
    };
  });
}

function qText(d, lang) {
  return lang === "hi" && d.hi && d.hi.q ? d.hi.q : d.q;
}
function oText(d, i, lang) {
  if (i === null || i === undefined) return null;
  return lang === "hi" && d.optsHi && d.optsHi[i] ? d.optsHi[i] : d.opts[i];
}
function eText(d, lang) {
  return lang === "hi" && d.hi && d.hi.e ? d.hi.e : d.e;
}
const HI_DONE = {};
BANK.forEach((c) => { HI_DONE[c.ch] = c.qs.every((q) => q.hi); });

function clock(s) {
  return Math.floor(s / 60) + ":" + String(s % 60).padStart(2, "0");
}

// ---------- scripture ----------
function parseRef(r) {
  const m = /^Mark (\d+):(.*)$/.exec(r);
  if (!m) return null;
  const nums = [];
  m[2].split(",").forEach((part) => {
    const p = part.trim();
    if (p.indexOf("-") > -1) {
      const b = p.split("-").map(Number);
      for (let i = b[0]; i <= b[1]; i++) nums.push(i);
    } else nums.push(Number(p));
  });
  return { ch: Number(m[1]), nums };
}

function passage(refStr, book, wide) {
  const p = parseRef(refStr);
  if (!p) return null;
  const arr = book[p.ch - 1] || [];
  let list = p.nums.slice();
  let clipped = false;
  if (wide) {
    const lo = Math.max(1, Math.min.apply(null, p.nums) - 2);
    const hi = Math.min(arr.length, Math.max.apply(null, p.nums) + 2);
    list = [];
    for (let i = lo; i <= hi; i++) list.push(i);
  } else if (list.length > 4) {
    list = list.slice(0, 4);
    clipped = true;
  }
  return {
    clipped,
    cited: p.nums,
    verses: list.filter((n) => arr[n - 1]).map((n) => ({ n, text: arr[n - 1] })),
  };
}

const BOOKS = { web: WEB, kjv: KJV, hin: HIN };
const TRLABEL = { web: "WEB", kjv: "KJV", hin: "हिन्दी" };

